from html.parser import HTMLParser
from pathlib import Path
import sys,json,re,hashlib
class Links(HTMLParser):
 def __init__(self):
  super().__init__(); self.href=None; self.links=[]; self.parts=[]; self.page=[]
 def handle_starttag(self, tag, attrs):
  if tag=='a': self.href=dict(attrs).get('href',''); self.parts=[]
 def handle_data(self, data):
  self.page.append(data)
  if self.href is not None: self.parts.append(data)
 def handle_endtag(self,tag):
  if tag=='a' and self.href is not None:
   self.links.append((self.href,' '.join(' '.join(self.parts).split()))); self.href=None
p=Path(sys.argv[1]); raw=p.read_bytes(); h=Links(); h.feed(raw.decode('utf-8','replace'))
notices=[(u,t) for u,t in h.links if re.search(r'tenderdetails|rfxtender|rf x'.replace(' ',''),u,re.I)]; result={'sha256':hashlib.sha256(raw).hexdigest(),'notice_link_count':len(notices),'notice_links':notices,'other_links':[(u,t) for u,t in h.links if t][:35]}
Path(sys.argv[2]).write_text(json.dumps(result,indent=2)); print(json.dumps({**result,'notice_links':notices[:45]}))
